<?php
namespace App\Policies;
use App\Models\{ConstructionIssue,User}; use App\Policies\Concerns\CompanyOwnedPolicy;
class ConstructionIssuePolicy { use CompanyOwnedPolicy; public function viewAny(User $u):bool{return $this->canForResource($u,'view_any_construction_issue');} public function view(User $u,ConstructionIssue $r):bool{return $this->canForRecord($u,'view_construction_issue',$r);} public function create(User $u):bool{return $this->canForResource($u,'create_construction_issue');} public function update(User $u,ConstructionIssue $r):bool{return $this->canForRecord($u,'update_construction_issue',$r);} public function start(User $u,ConstructionIssue $r):bool{return $this->canForRecord($u,'start_construction_issue',$r);} public function resolve(User $u,ConstructionIssue $r):bool{return $this->canForRecord($u,'resolve_construction_issue',$r);} public function close(User $u,ConstructionIssue $r):bool{return $this->canForRecord($u,'close_construction_issue',$r);} public function delete(User $u,ConstructionIssue $r):bool{return false;} }
